import json
import os
from collections import Counter

def main():
    path = os.path.join("дані", "користувачі.json")
    with open(path, encoding="utf-8") as f:
        users = json.load(f)

    counts = Counter()
    for user in users:
        email = str(user.get("email", "")).strip().lower()
        if email:
            counts[email] += 1

    for email in sorted(counts):
        if counts[email] > 1:
            print(f"{email} {counts[email]}")

if __name__ == "__main__":
    main()
